export function translateText(s,lang){if(lang==='zh')return chineseInterface[s]||s.replace(/^STAGE /,'阶段 ').replace(/^FIELD CASE \/ /,'田间情境 / ').replace(/^QUESTION \/ /,'题目 / ').replace('碳氮学习园 · C:N Learning Garden','碳氮学习园');const index=lang==='ms'?1:0;if(ui[s])return ui[s][index];
 const replacements=[[/^已学 (\d+) \/ 6 课$/,(_,n)=>index?`${n} / 6 pelajaran selesai`:`${n} / 6 lessons completed`], [/^已回答 (\d+) \/ 6 题 · 当前答对 (\d+) 题$/,(_,n,k)=>index?`${n} / 6 dijawab · ${k} betul`:`${n} / 6 answered · ${k} correct`], [/^本次答对 (\d+) \/ 6 题。你可以修改答案再练习。$/,(_,n)=>index?`${n} / 6 betul. Anda boleh mengubah jawapan untuk berlatih lagi.`:`${n} / 6 correct. You can change answers to practise again.`], [/^查看来源 (.+)$/,(_,id)=>index?`Lihat sumber ${id}`:`View source ${id}`], [/^情境 (\d+) 的答案$/,(_,n)=>index?`Jawapan situasi ${n}`:`Answers for scenario ${n}`], [/^第 (\d+) 题答案$/,(_,n)=>index?`Jawapan soalan ${n}`:`Answers for question ${n}`]];
 for(const [pattern,fn] of replacements)if(pattern.test(s))return s.replace(pattern,fn);
 let out=s.replace('（干基质量比）',index?' (nisbah jisim bahan kering)':' (dry-basis mass ratio)').replace('：先记住这个结论',index?': rumusan utama':': the key takeaway').replace('C:N LEARNING GARDEN /',index?'TAMAN PEMBELAJARAN C:N /':'C:N LEARNING GARDEN /').replace('碳氮学习园 · C:N Learning Garden',index?'Taman Pembelajaran C:N':'C:N Learning Garden');
 out=out.replace(/^(大学推广|官方推广|原始研究|研究摘要|化学数据库)( · .+)$/,(_,type,id)=>ui[type][index]+id);
 out=out.replace(/^STAGE /,index?'PERINGKAT ':'STAGE ').replace(/^FIELD CASE \/ /,index?'SITUASI KEBUN / ':'FIELD CASE / ').replace(/^QUESTION \/ /,index?'SOALAN / ':'QUESTION / ');
 for(const prefix of ['再想一步：','正确理解：'])if(out.startsWith(prefix))out=ui[prefix][index]+out.slice(prefix.length);
 if(out.includes(' · 碳氮学习园'))out=out.replace(' · 碳氮学习园',index?' · Taman Pembelajaran C:N':' · C:N Learning Garden');
 return out;
}
